// =====================================================================
// NÓ "Contexto do gestor"
// =====================================================================
// Resolve o que NÃO pode passar pelo LLM: quem está perguntando, quais
// empresas ele pode ver, qual departamento o restringe, e que instante
// é "agora". O escopo entra aqui e nunca é reaberto depois.
// =====================================================================

const raw = $input.first().json;
const body = raw.body || raw || {};

const parseLista = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v.map((x) => String(x).trim()).filter(Boolean);
  return String(v).split(';').map((x) => x.trim()).filter(Boolean);
};

// Allowlist de empresas: resolvido no banco pelo 7.1, nunca pelo LLM.
const empresas_ids = String(body.empresas_ids || body.empresa_id || '')
  .split(/[;,]/)
  .map((s) => s.trim())
  .filter((s) => /^\d+$/.test(s));

if (!empresas_ids.length) {
  throw new Error('Contexto sem empresa autorizada: o 7.1 precisa enviar empresas_ids ou empresa_id.');
}

const tipo_gestor = body.tipo_gestor || 'gestor_full';

// depto_gestor pode chegar como string ("comercial") ou objeto {id,nome}
let depto_gestor = body.depto_gestor || null;
if (typeof depto_gestor === 'string') depto_gestor = { id: null, nome: depto_gestor };

if (tipo_gestor === 'gestor_depto' && !(depto_gestor && (depto_gestor.id || depto_gestor.nome))) {
  throw new Error('Gestor de departamento sem depto_gestor no body: consulta bloqueada.');
}

const pergunta = (body.pergunta || '').toString().trim();
if (!pergunta) throw new Error('Body sem "pergunta".');

return [{
  json: {
    pergunta,
    chat_id: body.chat_id || null,
    empresas_ids,
    consolidado: empresas_ids.length > 1,
    tipo_gestor,
    depto_gestor,
    // Empresas do grupo que o gestor VÊ mas que não têm o serviço de IA
    // contratado. O 7.1 já as tirou de empresas_ids — elas vêm aqui só
    // para a resposta poder dizer que o consolidado não cobre o grupo
    // inteiro, em vez de entregar um total silenciosamente menor.
    empresas_sem_servico: parseLista(body.empresas_sem_servico),
    // Unidades (empresa OU filial) que perderam o serviço contratado.
    // Diferente de empresas_sem_servico, que é texto para a resposta:
    // esta é a lista de IDS que o gate de escopo USA para excluir.
    // Existe porque a empresa contratada pode estar no branch_id e não
    // no company_id: na FIOS, as 32 pessoas da RED têm company_id 1214
    // (a WHITE, que tem serviço) e branch_id 1444 (que não tem). Filtrar
    // só por company_id não exclui nenhuma delas.
    unidades_sem_servico_ids: String(body.unidades_sem_servico_ids || '')
      .split(/[;,]/)
      .map((s) => s.trim())
      .filter((s) => /^\d+$/.test(s)),
    // Listas que o gestor tem direito de ver, usadas pelo interpretador
    // como vocabulário local. O que não vem aqui, ele consulta por tool.
    contexto_disponivel: {
      filiais: parseLista(body.filiais),
      centros_de_custo: parseLista(body.centros_de_custo),
      cargos: parseLista(body.cargos),
      departamentos: parseLista(body.departamentos),
    },
    // Instante único da execução: todo cálculo de data usa este valor,
    // então a mesma pergunta é reprodutível em teste.
    agora: new Date().toISOString(),
    tentativa: 1,
  },
}];

// =====================================================================
// NÓ "Catálogo"  —  ÚNICA FONTE DE VERDADE DO 7.2
// =====================================================================
// Este nó não executa lógica: ele DECLARA o que existe.
// Três consumidores leem daqui:
//   1. o Interpretador (o prompt dele é gerado no fim deste arquivo)
//   2. o Motor de consulta (valida e compila contra estas declarações)
//   3. o Fallback SQL restrito (recebe estes nomes como schema)
//
// Para suportar uma pergunta nova, declare um CAMPO aqui. Não existe
// mais "mapear pergunta": as perguntas são combinações destes campos.
//
// Os pontos marcados [CONFIRMAR: bloco N] dependem do resultado do
// script mapeamento-banco-bms.sql. Estão isolados de propósito.
// =====================================================================

const VERSAO_CATALOGO = '2.0.0-dev';

// ---------------------------------------------------------------------
// Fragmentos SQL reaproveitados
// ---------------------------------------------------------------------

const SQL_CID_CAPITULO = `CASE
    WHEN c_cid.code_cid LIKE 'A%' OR c_cid.code_cid LIKE 'B%' THEN 'A00-B99 - Doenças infecciosas e parasitárias'
    WHEN c_cid.code_cid LIKE 'C%' OR c_cid.code_cid LIKE 'D0%' OR c_cid.code_cid LIKE 'D1%'
      OR c_cid.code_cid LIKE 'D2%' OR c_cid.code_cid LIKE 'D3%' OR c_cid.code_cid LIKE 'D4%' THEN 'C00-D48 - Neoplasias'
    WHEN c_cid.code_cid LIKE 'D5%' OR c_cid.code_cid LIKE 'D6%' OR c_cid.code_cid LIKE 'D7%'
      OR c_cid.code_cid LIKE 'D8%' THEN 'D50-D89 - Doenças do sangue'
    WHEN c_cid.code_cid LIKE 'E%' THEN 'E00-E90 - Doenças endócrinas, nutricionais e metabólicas'
    WHEN c_cid.code_cid LIKE 'F%' THEN 'F00-F99 - Transtornos mentais e comportamentais'
    WHEN c_cid.code_cid LIKE 'G%' THEN 'G00-G99 - Doenças do sistema nervoso'
    WHEN c_cid.code_cid LIKE 'H0%' OR c_cid.code_cid LIKE 'H1%' OR c_cid.code_cid LIKE 'H2%'
      OR c_cid.code_cid LIKE 'H3%' OR c_cid.code_cid LIKE 'H4%' OR c_cid.code_cid LIKE 'H5%' THEN 'H00-H59 - Doenças do olho'
    WHEN c_cid.code_cid LIKE 'H6%' OR c_cid.code_cid LIKE 'H7%' OR c_cid.code_cid LIKE 'H8%'
      OR c_cid.code_cid LIKE 'H9%' THEN 'H60-H95 - Doenças do ouvido'
    WHEN c_cid.code_cid LIKE 'I%' THEN 'I00-I99 - Doenças do aparelho circulatório'
    WHEN c_cid.code_cid LIKE 'J%' THEN 'J00-J99 - Doenças do aparelho respiratório'
    WHEN c_cid.code_cid LIKE 'K%' THEN 'K00-K93 - Doenças do aparelho digestivo'
    WHEN c_cid.code_cid LIKE 'L%' THEN 'L00-L99 - Doenças da pele'
    WHEN c_cid.code_cid LIKE 'M%' THEN 'M00-M99 - Doenças osteomusculares'
    WHEN c_cid.code_cid LIKE 'N%' THEN 'N00-N99 - Doenças do aparelho geniturinário'
    WHEN c_cid.code_cid LIKE 'O%' THEN 'O00-O99 - Gravidez, parto e puerpério'
    WHEN c_cid.code_cid LIKE 'R%' THEN 'R00-R99 - Sintomas e achados anormais'
    WHEN c_cid.code_cid LIKE 'S%' OR c_cid.code_cid LIKE 'T%' THEN 'S00-T98 - Lesões e envenenamentos'
    WHEN c_cid.code_cid LIKE 'Z%' THEN 'Z00-Z99 - Fatores que influenciam o estado de saúde'
    WHEN c_cid.code_cid IS NULL THEN 'Sem CID informado'
    ELSE 'Outros / Não classificado'
  END`;

// [CONFIRMADO: bloco 2] steps.name guarda chave i18n, não rótulo.
const SQL_ETAPA = `CASE s.[name]
      WHEN 'steps.register'   THEN 'Cadastro'
      WHEN 'steps.scheduling' THEN 'Agendamento de perícia'
      WHEN 'steps.benefits'   THEN 'Benefício'
      WHEN 'steps.renew'      THEN 'Prorrogação'
      WHEN 'steps.exam'       THEN 'Exame de retorno'
      WHEN 'steps.return'     THEN 'Retorno ao trabalho'
      ELSE COALESCE(s.[name], 'Não informado')
    END`;

// [CONFIRMADO: bloco 5a] benefit_status.description também é chave i18n.
const SQL_STATUS_BENEFICIO = `CASE bs.[description]
      WHEN 'benefit_status.deferido'   THEN 'Deferido'
      WHEN 'benefit_status.indeferido' THEN 'Indeferido'
      WHEN 'benefit_status.cessado'    THEN 'Cessado'
      ELSE COALESCE(bs.[description], 'Não informado')
    END`;

// [CONFIRMADO: bloco 5c] user_return.execution_date tem lixo histórico
// (existe registro com ano 0205). Data absurda vira NULL antes de
// qualquer DATEDIFF, MIN ou MAX.
const dataSegura = (col) => `CASE WHEN ${col} BETWEEN '1950-01-01' AND '2100-01-01' THEN ${col} END`;

// [CONFIRMADO: R3.5] absence_reason — 7 valores, i18n. É o
// "tipo_afastamento" que o prompt antigo prometia (Doença / Acidente /
// Maternidade) e que nunca existiu como campo: existia como ESTA tabela,
// que ninguém estava usando.
const SQL_MOTIVO_AFASTAMENTO = `CASE ar.[name]
      WHEN 'absenceReason.accidentAtWork'      THEN 'Acidente de trabalho'
      WHEN 'absenceReason.commutingAccident'   THEN 'Acidente de trajeto'
      WHEN 'absenceReason.occupationalDisease' THEN 'Doença ocupacional'
      WHEN 'absenceReason.ordinaryIllness'     THEN 'Doença comum'
      WHEN 'absenceReason.domesticAccident'    THEN 'Acidente doméstico'
      WHEN 'absenceReason.pregnancy'           THEN 'Gestação / maternidade'
      WHEN 'absenceReason.companion'           THEN 'Acompanhante'
      ELSE COALESCE(ar.[name], 'Não informado')
    END`;

const SQL_FAIXA_ETARIA = (alias) => `CASE
    WHEN ${alias}.nascimento IS NULL THEN 'Não informado'
    WHEN DATEDIFF(YEAR, ${alias}.nascimento, GETDATE()) < 20 THEN '< 20 anos'
    WHEN DATEDIFF(YEAR, ${alias}.nascimento, GETDATE()) BETWEEN 20 AND 29 THEN '20-29 anos'
    WHEN DATEDIFF(YEAR, ${alias}.nascimento, GETDATE()) BETWEEN 30 AND 39 THEN '30-39 anos'
    WHEN DATEDIFF(YEAR, ${alias}.nascimento, GETDATE()) BETWEEN 40 AND 49 THEN '40-49 anos'
    WHEN DATEDIFF(YEAR, ${alias}.nascimento, GETDATE()) BETWEEN 50 AND 59 THEN '50-59 anos'
    ELSE '60+ anos'
  END`;

// Joins comuns a partir de employee. Usado pelos três prelúdios.
const JOINS_PESSOA = `
    INNER JOIN [company]     c_matriz ON e.company_id      = c_matriz.id
    LEFT  JOIN [company]     c_filial ON e.branch_id       = c_filial.id
    LEFT  JOIN [department]  d        ON e.department_id   = d.id AND d.[delete] = 'N'
    LEFT  JOIN [position]    p        ON e.position_id     = p.id_position
    LEFT  JOIN [user]        u        ON e.user_id         = u.id_user
    LEFT  JOIN [user_gender] ug       ON u.gender_id       = ug.id
    LEFT  JOIN [cost_center] cc       ON e.cost_center_id  = cc.cost_center_id`;

// Colunas de pessoa. Idênticas nos três datasets — é o que faz
// "por filial" e "por cargo" funcionarem igual em qualquer pergunta.
const COLUNAS_PESSOA = `
        c_matriz.id                                          AS empresa_id,
        c_matriz.companyName                                 AS empresa,
        COALESCE(c_filial.companyName, c_matriz.companyName) AS filial,
        e.department_id                                      AS departamento_id,
        d.[name]                                             AS departamento,
        e.id_Employee                                        AS colaborador_id,
        u.[name]                                             AS colaborador,
        u.cpf                                                AS cpf,
        u.birthdate                                          AS nascimento,
        p.position_name                                      AS cargo,
        cc.[name]                                            AS centro_custo,
        ug.label                                             AS sexo,
        TRY_CONVERT(FLOAT, e.salary) / 100.0                 AS salario_mensal`;
//                                        ^^^^^^ [CONFIRMAR: bloco 11] escala do salário

// =====================================================================
// NOTAS DO MAPEAMENTO (rodada 1) — leia antes de mexer nos prelúdios
// =====================================================================
// ga_situation [bloco 1] — 12 valores, e `situacao` é o estado ATUAL do
//   afastamento, não um evento datado. Responde "quem está assim hoje";
//   NÃO responde "quantos estavam assim em março". O Motor marca essas
//   consultas com uma ressalva para a Mindy avisar o gestor.
//   1 Afastado · 2 Perícia · 3 Deferido · 4 Beneficiário não localizado
//   5 Limbo · 6 Aposentadoria por invalidez · 7 Prorrogação
//   8 Exame retorno · 9 Retorno · 10 Retorno sem Benefício
//   11 Demitido · 12 Aposentadoria por idade
//   Nenhum caso entrou em Limbo desde 08/12/2025 (464 no total).
//
// steps [bloco 2] — steps.name é chave i18n, não rótulo. Mapeado em
//   SQL_ETAPA. Sem isso o gestor lê "steps.benefits" na resposta e o
//   filtro por "Perícia" volta vazio.
//
// benefit_status [bloco 5a] — também i18n ("benefit_status.cessado").
//   Mapeado em SQL_STATUS_BENEFICIO. 672 dos 806 estão cessados.
//
// benefit_type [bloco 4] — código é numérico puro ('31', '91'), sem "B"
//   e sem zero à esquerda. Acidentário = 91/92/93/94 está correto.
//   Cuidado: '36' (Auxílio Acidente) é previdenciário, NÃO acidentário.
//
// user_return [bloco 5c + R2.1/R2.5] — return_status é i18n:
//   1 = returnStatus.eligible, 2 = returnStatus.ineligible. ATENÇÃO:
//   "eligible" é APTIDÃO no exame de retorno, não "retorno efetivado".
//   Os 158 inelegíveis também têm execution_date. Ver nota sobre
//   data_retorno abaixo.
//   Lixo de data confirmado e pequeno: 1 em user_return.execution_date
//   (ano 0205), 10 em user_benefit.start_date antes de 1950, e 2 em
//   user_medical_info.start_date no futuro. dataSegura() cobre.

// status_medical [R2.1] — também i18n: statusMedical.waiting /
//   .approved / .refused, ids 1/2/3. O CASE do prelúdio está correto.

// status_expertise [R2.1] — 5 valores, e estes vêm em PORTUGUÊS:
//   EM ANÁLISE · EXIGÊNCIA · AGUARDANDO · ACERTO PARA MARCAÇÃO ·
//   ACERTO PÓS PERÍCIA, com flag in_person (S nos dois últimos).
//   É o status de perícia que o prompt antigo prometia como
//   `resultado_pericia` e nunca entregou. Falta descobrir por qual
//   tabela ele se liga a user_steps -> rodada 3.

// HISTÓRICO [R2.6 + R3.2] — RESOLVIDO e integrado.
//   ga_situation_history é lista encadeada: (user_steps_id,
//   ga_situation_id, date_start_ga) + previous_ga_situation_history_id.
//   Não tem data de fim — o fim de um período é o início do seguinte,
//   que o LEAD() resolve. Virou o dataset `situacao_periodo`.
//   2.315 linhas, de 01/07/2025 a 24/08/2026. A cobertura começa em
//   07/2025: consulta anterior a isso é recusada, e consulta que
//   atravessa a borda leva ressalva.
//   steps_history tem a MESMA forma (date_start_steps) com 2.251
//   linhas — dá um `etapa_periodo` de graça quando fizer falta.
//
// VIEWS [R3.1] — existem 4: user_employee_view, vw_Rubricas_Classificadas,
//   vw_user_event_timeline, vw_user_steps_timeline. O corpo delas veio
//   NULL (o login não tem VIEW DEFINITION), mas dá para consultar
//   colunas e conteúdo. Pendente na rodada 4: podem substituir parte
//   do prelúdio, e vw_Rubricas_Classificadas é folha (fora do 7.2).
//
// user_benefit [R3.4] — o print da UI casa assim:
//   DDB = dispatch_date · DIB = start_date · DCB = end_date
//   Prorrogação = extension ('S'/'N') · Tipo nexo = tipo_nexo_id
//   "Benefícios para cessar" usa data_fim (DCB) — estava certo.
//
// absence_reason [R3.5] — 7 valores i18n, e ninguém usava:
//   accidentAtWork · commutingAccident · occupationalDisease ·
//   ordinaryIllness · domesticAccident · pregnancy · companion.
//   É o "tipo_afastamento" (Doença/Acidente/Maternidade) que o prompt
//   antigo prometia sem ter campo. Virou `motivo_afastamento`.
//
// perícia [R3.6 + R4.1] — RESOLVIDO. expertise_assessment tem 887
//   linhas com DATA e hora do agendamento, protocolo, in_person e
//   statusExpertiseIdStatusExpertise. Então "perícia agendada" passou a
//   ter data de verdade (is_pericia_agendada = data >= hoje), em vez do
//   gaSituation = 2 que o 7.2 atual usa e que só diz "está na etapa".
//   Um afastamento pode ter várias perícias (o 1616 tem duas), então
//   OUTER APPLY pela data mais recente.
//   integration_dataprev tem só 24 linhas e liga por CPF/NB, não por
//   user_steps: é tabela de carga, não serve como fonte ainda. Fica de
//   fora, mas tem conclusao_pericia_medica e nexo_tecnico — vale
//   revisitar quando a BMS estiver importando de verdade.

// CAUDA DO HISTÓRICO [R4.4] — o achado mais sério da rodada 4.
//   Dos 1.608 afastamentos, 1.001 têm histórico e 607 não.
//   E a última linha do histórico DIVERGE da situação atual em muitos
//   casos: histórico diz "Limbo" (set/2025), user_steps diz "Retorno".
//   Ou seja, a transição para Retorno não foi gravada no histórico.
//   Como o LEAD() devolve NULL na última linha, tratar NULL como
//   "ainda nessa situação" superestimaria limbo em datas passadas.
//   Tratado com is_periodo_indeterminado + ressalva obrigatória.
//   Isto é bug de gravação na aplicação da BMS, e vale reportar: se
//   corrigirem, o dataset histórico fica confiável de verdade.

// user_employee_view [R4.2] — a view traz is_pcd (bit!), enrollment
//   (matrícula), admission_date, demission_date, civil_status_id,
//   ethnicity_id, e empresa+filial já resolvidas. Usei is_pcd,
//   enrollment e admission_date via LEFT JOIN.
//   is_pcd fecha uma lacuna da rodada 1: o prompt antigo prometia
//   `pcd: "Sim"|"Não"` e o compilador descartava em silêncio.
//   DELIBERADAMENTE NÃO exposto: ethnicity_id. Raça/etnia é dado
//   sensível sob a LGPD e fatiar absenteísmo por ela não é análise de
//   RH, é risco. is_pcd entrou porque cota de PCD é obrigação legal,
//   mas marcado como sensivel: só agregado, nunca lista nominal.

// vw_user_steps_timeline / vw_user_event_timeline [R4.2] — as duas são
//   IDÊNTICAS (mesmas colunas, mesmo conteúdo) e trazem eventos de
//   BENEFÍCIO (BENEFICIO_DEFERIDO/INDEFERIDO/CESSADO) com event_date e
//   next_event_date, já com o LEAD aplicado. Não são timeline de
//   situação, como o nome sugere.
//   Cuidado: a primeira linha do exemplo aponta para si mesma
//   (INDEFERIDO -> INDEFERIDO na mesma data), então a view tem
//   duplicação. Não usei por isso — mas é a base pronta para um
//   dataset de eventos de benefício quando a duplicação for resolvida.

// tipo_nexo_id [R4.5] — não existe tabela de domínio ('%nexo%' não
//   retorna nada) e vem nulo nos exemplos. REMOVIDO do catálogo: id sem
//   rótulo e sem dado não serve para ninguém.

// reason_change_benefit_type [R4.3] — administrativo / judicial (i18n).
//   É o "Motivo" do print da UI. Virou motivo_alteracao_especie.
//
// fan-out na prática [R3.7] — nos últimos 18 meses, contagem com e sem
//   DISTINCT é IGUAL em todas as empresas. Os 10 casos com 2+
//   benefícios são antigos. O OUTER APPLY continua certo como proteção,
//   mas o impacto hoje é zero — eu havia chamado isso de bug ativo e
//   não é.
//
// onde estão os dados [R3.8] — empresa 24 (EARTH SA) tem 222
//   afastamentos E 163 atestados: é a melhor para o golden set.
//   A 23 tem 344 afastamentos e só 1 atestado. E a 1446 (Supermercado
//   Paraná), que está hardcoded no nó Edit Fields do 7.2 atual, não
//   aparece no top 10 de nada: o teste manual do fluxo atual roda
//   contra uma empresa praticamente vazia.
//
// medical_release [bloco 6 + R2.2] — NÃO existe tabela de domínio. O
//   cruzamento com situação mostrou que valor 2 (247) concentra em
//   Retorno (197), Exame retorno (30) e Retorno sem Benefício (9): é
//   alta médica CONCEDIDA. Valor 1 (12) está espalhado por Limbo,
//   Perícia, Deferido, Retorno e Aposentadoria — parece legado.
//   Ou seja: `IN (1,2)` NÃO é "alta antecipada", como o 7.2 atual assume.
//   O campo virou `tem_alta_medica` (honesto) + `alta_medica_tipo`
//   (o valor cru), e "alta antecipada" saiu do catálogo até a BMS
//   dizer o que 1 e 2 significam. É pergunta de produto, não de dado.
//
// department [bloco 7] — TEM company_id (NOT NULL), e só "NA" (16) e
//   "TESTE OPERACOES" (2) repetem nome entre empresas. O filtro por
//   nome deixou de ser workaround: virou join dentro do escopo.
//
// user_medical_examination [bloco 8] — tem date_exam e delete_datetime,
//   e NÃO tem tipo de exame. "Admissional", "periódico" e "demissional",
//   que o prompt antigo prometia, não existem nesta base. 24 afastamentos
//   têm 2 ou 3 exames -> OUTER APPLY obrigatório.
//
// user_benefit [bloco 9] — 8 afastamentos com 2 benefícios e 2 com 3.
//   O LEFT JOIN do 7.2 atual duplica linha nesses 10. OUTER APPLY resolve.
//
// register_absence [bloco 9b/10] — vínculo 1:1 (263 registros) e TEM
//   delete_datetime, que o 7.2 atual não filtra: vínculo apagado ainda
//   conta como "virou afastamento".
//
// employee.salary [bloco 11 + R2.3] — RESOLVIDO, e a resposta é ruim:
//   a coluna está VAZIA na prática. Mediana = 100, e p10 a p90 todos
//   = 100, para qualquer cargo (de ELETRICISTA a CONSULTOR). Só ~1%
//   tem valor real (esses sim em centavos: 191207 = R$ 1.912,07).
//   E 419 linhas contêm a STRING "undefined" — bug de JS que vazou
//   para o banco.
//   Não é ambiguidade de escala: é placeholder. Qualquer métrica de
//   custo daria R$ 3,33/mês para 99% das pessoas. custo_estimado e
//   salario_mensal ficam FORA do catálogo — não é limitação nossa,
//   é dado que a BMS precisa corrigir na origem.
//
// user_medical_info [bloco 12 + R2.4] — consecutive_days nulo em 57 de
//   772 e divergente do DATEDIFF em 23; o COALESCE cobre.
//   consecutive_hours é MINUTOS, confirmado: os 7 registros são 420
//   (7h, jornada cheia), 320, 240, 120 e 90 (1h30), todos com
//   start_date = end_date. O 7.2 atual estava certo em dividir por
//   1440; a versão anterior deste catálogo dividia por 24 e estava
//   errada por 60x. Corrigido.
//
// volumetria [bloco 13] — user_steps 1.608 · user_medical_info 772 ·
//   user_benefit 806 · employee 34.908. O prelúdio em CTE é barato.
//
// índices [bloco 14] — só as chaves primárias. Nenhum índice em
//   employee.company_id nem nas colunas de data. Nestes volumes não
//   dói, e é por isso que o escopo entra DENTRO da CTE.
// =====================================================================

// ---------------------------------------------------------------------
// PRELÚDIO 1 — ds_afastamento (grão: 1 linha = 1 afastamento)
// ---------------------------------------------------------------------
const PRELUDIO_AFASTAMENTO = `ds_afastamento AS (
    SELECT
        us.id_user_steps                                     AS afastamento_id,
${COLUNAS_PESSOA},
        c_cid.code_cid                                       AS cid_codigo,
        c_cid.[description]                                  AS cid_descricao,
        ${SQL_CID_CAPITULO}                                  AS cid_capitulo,
        gs.[description]                                     AS situacao,
        ${SQL_ETAPA}                                         AS etapa,
        ${SQL_MOTIVO_AFASTAMENTO}                            AS motivo_afastamento,
        CASE WHEN ar.id_absence_reason IN (2, 3, 5) THEN 1 ELSE 0 END AS is_acidente_ou_ocupacional,
        CASE WHEN hst.qtd IS NULL THEN 0 ELSE 1 END          AS tem_historico_situacao,
        CASE WHEN us.gaSituationIdGaSituation = 5 THEN 1 ELSE 0 END  AS is_limbo,
        CASE WHEN us.gaSituationIdGaSituation = 2 THEN 1 ELSE 0 END  AS is_em_pericia,
        CASE WHEN us.gaSituationIdGaSituation IN (9, 10) THEN 1 ELSE 0 END AS is_retornado,
        CASE WHEN us.medical_release IN (1, 2)   THEN 1 ELSE 0 END   AS tem_alta_medica,
        us.medical_release                                           AS alta_medica_tipo,
        us.last_day_worked                                           AS ultimo_dia_trabalhado,
        CASE WHEN war.id_work_accident_reporting IS NOT NULL
                  OR ben.especie_codigo IN ('91','92','93','94')
             THEN 1 ELSE 0 END                               AS is_acidentario,
        CASE WHEN war.id_work_accident_reporting IS NOT NULL THEN 1 ELSE 0 END AS is_cat_registrada,
        CASE WHEN exa.id_exame IS NOT NULL THEN 1 ELSE 0 END AS is_exame,
        per.data_pericia                                     AS data_pericia,
        per.status_pericia                                   AS status_pericia,
        per.protocolo_pericia                                AS protocolo_pericia,
        CASE WHEN per.presencial = 'S' THEN 1 ELSE 0 END     AS pericia_presencial,
        CASE WHEN per.data_pericia >= CAST(GETDATE() AS DATE) THEN 1 ELSE 0 END AS is_pericia_agendada,
        uev.is_pcd                                           AS is_pcd,
        uev.enrollment                                       AS matricula,
        uev.admission_date                                   AS data_admissao,
        ben.especie_codigo                                   AS especie_codigo,
        ben.especie                                          AS especie_beneficio,
        ben.inicio                                           AS beneficio_inicio,
        ben.fim                                              AS beneficio_fim,
        exa.data_exame                                       AS data_exame,
        ${dataSegura('us.date_absence')}                     AS data_afastamento,
        ${dataSegura('ur.execution_date')}                   AS data_retorno,
        DATEDIFF(day, ${dataSegura('us.date_absence')},
                 COALESCE(${dataSegura('ur.execution_date')}, CAST(GETDATE() AS DATE)))  AS dias_afastado
    FROM [user_steps] us
    INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee
${JOINS_PESSOA}
    LEFT  JOIN [steps]        s     ON us.stepsIdSteps            = s.id_steps
    LEFT  JOIN [ga_situation] gs    ON us.gaSituationIdGaSituation = gs.id_ga_situation
    LEFT  JOIN [cid]          c_cid ON us.cidIdCid                = c_cid.id_cid
    LEFT  JOIN [absence_reason] ar  ON us.absenceReasonIdAbsenceReason = ar.id_absence_reason
    OUTER APPLY (
        SELECT COUNT(*) AS qtd
        FROM [ga_situation_history] h_c
        WHERE h_c.user_steps_id = us.id_user_steps AND h_c.delete_datetime IS NULL
        HAVING COUNT(*) > 0
    ) hst
    LEFT  JOIN [work_accident_reporting] war
           ON us.workAccidentIdWorkAccidentReporting = war.id_work_accident_reporting
    LEFT  JOIN [user_return] ur
           ON ur.userStepsIdUserSteps = us.id_user_steps AND ur.return_status_id = 1
    OUTER APPLY (
        SELECT TOP 1 bt.benefit_type_code        AS especie_codigo,
                     bt.benefit_type_description AS especie,
                     ub.start_date               AS inicio,
                     ub.end_date                 AS fim
        FROM [user_benefit] ub
        LEFT JOIN [benefit_type] bt ON ub.benefitTypeIdBenefitType = bt.id_benefit_type
        WHERE ub.userStepsIdUserSteps = us.id_user_steps AND ub.[delete] = 'N'
        ORDER BY ub.start_date DESC, ub.id_user_benefit DESC
    ) ben
    LEFT JOIN [user_employee_view] uev ON uev.id_Employee = e.id_Employee
    OUTER APPLY (
        SELECT TOP 1 ea.[date]                       AS data_pericia,
                     se.status_status_expertise      AS status_pericia,
                     ea.protocol                     AS protocolo_pericia,
                     ea.in_person                    AS presencial
        FROM [expertise_assessment] ea
        LEFT JOIN [status_expertise] se ON ea.statusExpertiseIdStatusExpertise = se.id_status_expertise
        WHERE ea.userStepsIdUserSteps = us.id_user_steps
          AND ea.delete_datetime IS NULL AND ea.[delete] = 'N'
        ORDER BY ea.[date] DESC, ea.id_expertise_assessment DESC
    ) per
    OUTER APPLY (
        SELECT TOP 1 ume.id_user_medical_examination AS id_exame,
                     ume.date_exam                   AS data_exame
        FROM [user_medical_examination] ume
        WHERE ume.userStepsIdUserSteps = us.id_user_steps
          AND ume.delete_datetime IS NULL
        ORDER BY ume.date_exam DESC
    ) exa
    WHERE us.[delete] = 'N'
      /*{{ESCOPO}}*/
)`;

// ---------------------------------------------------------------------
// PRELÚDIO 2 — ds_atestado (grão: 1 linha = 1 atestado)
// ---------------------------------------------------------------------
const PRELUDIO_ATESTADO = `ds_atestado AS (
    SELECT
        umi.id_user_medical_info                             AS atestado_id,
${COLUNAS_PESSOA},
        c_cid.code_cid                                       AS cid_codigo,
        c_cid.[description]                                  AS cid_descricao,
        ${SQL_CID_CAPITULO}                                  AS cid_capitulo,
        umi.doctor_name                                      AS medico,
        CASE umi.statusMedicalIdStatusMedical
             WHEN 1 THEN 'Aguardando'
             WHEN 2 THEN 'Aprovado'
             WHEN 3 THEN 'Recusado'
             ELSE 'Outro' END                                AS status_atestado,
        umi.statusMedicalIdStatusMedical                     AS status_atestado_id,
        CASE WHEN umi.is_hours_certificates = 1 THEN 1 ELSE 0 END AS is_por_horas,
        CASE WHEN ra.id IS NOT NULL THEN 1 ELSE 0 END        AS is_vinculado_afastamento,
        ra.user_steps_id                                     AS afastamento_id,
        ${dataSegura('umi.start_date')}                      AS data_inicio,
        ${dataSegura('umi.end_date')}                        AS data_fim,
        CAST(umi.create_datetime AS DATE)                    AS data_registro,
        CASE WHEN umi.is_hours_certificates = 1
             THEN COALESCE(umi.consecutive_hours, 0) / 1440.0
             ELSE COALESCE(umi.consecutive_days,
                           DATEDIFF(day, umi.start_date,
                                    COALESCE(umi.end_date, umi.start_date)) + 1)
        END                                                  AS dias_ausencia
    FROM [user_medical_info] umi
    INNER JOIN [employee] e ON umi.employeeIdEmployee = e.id_Employee
${JOINS_PESSOA}
    LEFT JOIN [cid] c_cid ON umi.cidIdCid = c_cid.id_cid
    OUTER APPLY (
        SELECT TOP 1 ra_i.id, ra_i.user_steps_id
        FROM [register_absence] ra_i
        WHERE ra_i.user_medical_info_id = umi.id_user_medical_info
          AND ra_i.delete_datetime IS NULL
        ORDER BY ra_i.id DESC
    ) ra
    WHERE umi.delete_datetime IS NULL
      /*{{ESCOPO}}*/
)`;

// ---------------------------------------------------------------------
// PRELÚDIO 3 — ds_beneficio (grão: 1 linha = 1 benefício)
// ---------------------------------------------------------------------
const PRELUDIO_BENEFICIO = `ds_beneficio AS (
    SELECT
        ub.id_user_benefit                                   AS beneficio_id,
        ub.benefit_number                                    AS numero_beneficio,
${COLUNAS_PESSOA},
        COALESCE(bt_change.benefit_type_description,
                 bt.benefit_type_description)                AS especie_beneficio,
        COALESCE(bt_change.benefit_type_code,
                 bt.benefit_type_code)                       AS especie_codigo,
        ${SQL_STATUS_BENEFICIO}                              AS status_beneficio,
        CASE WHEN COALESCE(bt_change.benefit_type_code, bt.benefit_type_code)
                  IN ('91','92','93','94') THEN 1 ELSE 0 END AS is_acidentario,
        CASE WHEN ucb.id_user_change_benefit IS NOT NULL THEN 1 ELSE 0 END AS is_especie_alterada,
        CASE rcb.[description]
             WHEN 'reason_change_benefit_type.administrativo' THEN 'Administrativo'
             WHEN 'reason_change_benefit_type.judicial'       THEN 'Judicial'
             ELSE rcb.[description]
        END                                                  AS motivo_alteracao_especie,
        ${dataSegura('ucb.date_change_benefit_type')}        AS data_alteracao_especie,
        c_cid.code_cid                                       AS cid_codigo,
        c_cid.[description]                                  AS cid_descricao,
        ${SQL_CID_CAPITULO}                                  AS cid_capitulo,
        ${dataSegura('ub.dispatch_date')}                    AS data_despacho,
        CASE WHEN ub.extension = 'S' THEN 1 ELSE 0 END       AS is_prorrogacao,
        ${dataSegura('ub.start_date')}                       AS data_inicio,
        ${dataSegura('ub.end_date')}                         AS data_fim,
        ${dataSegura('us.date_absence')}                     AS data_afastamento,
        DATEDIFF(day, ${dataSegura('ub.start_date')},
                 COALESCE(${dataSegura('ub.end_date')}, CAST(GETDATE() AS DATE))) AS dias_beneficio
    FROM [user_benefit] ub
    LEFT  JOIN [benefit_type]   bt ON ub.benefitTypeIdBenefitType   = bt.id_benefit_type
    LEFT  JOIN [benefit_status] bs ON ub.benefitStatusIdBenefitStatus = bs.id_benefit_status
    LEFT  JOIN [user_change_benefit] ucb
           ON ub.id_user_benefit = ucb.user_benefit_id AND ucb.delete_datetime IS NULL
    LEFT  JOIN [benefit_type] bt_change ON ucb.change_benefit_type = bt_change.id_benefit_type
    LEFT  JOIN [reason_change_benefit_type] rcb
           ON ucb.reasonChangeBenefitTypeIdReasonChangeBenefitType = rcb.id_reason_change_benefit_type
    INNER JOIN [user_steps] us ON ub.userStepsIdUserSteps = us.id_user_steps
    LEFT  JOIN [cid] c_cid ON us.cidIdCid = c_cid.id_cid
    INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee
${JOINS_PESSOA}
    WHERE ub.[delete] = 'N'
      /*{{ESCOPO}}*/
)`;

// ---------------------------------------------------------------------
// PRELÚDIO 4 — ds_situacao_periodo
// (grão: 1 linha = 1 período em que um afastamento ficou numa situação)
// ---------------------------------------------------------------------
// ga_situation_history é uma lista encadeada: cada linha diz que o
// afastamento ENTROU numa situação em date_start_ga. Não há data de
// saída — o fim de um período é o início do período seguinte do mesmo
// afastamento, que o LEAD() resolve.
//
// Isto é o que torna respondível "quantos estavam em limbo em março?".
// Cobertura: o histórico começa em 01/07/2025 (2.315 linhas). Antes
// disso não existe registro, então consulta de situação em data
// anterior a julho/2025 não tem resposta — o Motor avisa.
const PRELUDIO_SITUACAO_PERIODO = `ds_situacao_periodo AS (
    SELECT
        h.id_ga_situation_history                            AS periodo_id,
        h.user_steps_id                                      AS afastamento_id,
${COLUNAS_PESSOA},
        gs.[description]                                     AS situacao,
        CASE WHEN h.ga_situation_id = 5 THEN 1 ELSE 0 END    AS is_limbo,
        CASE WHEN h.ga_situation_id = 2 THEN 1 ELSE 0 END    AS is_em_pericia,
        CASE WHEN h.ga_situation_id IN (9, 10) THEN 1 ELSE 0 END AS is_retornado,
        ${SQL_MOTIVO_AFASTAMENTO}                            AS motivo_afastamento,
        c_cid.code_cid                                       AS cid_codigo,
        c_cid.[description]                                  AS cid_descricao,
        ${SQL_CID_CAPITULO}                                  AS cid_capitulo,
        h.date_start_ga                                      AS inicio,
        LEAD(h.date_start_ga) OVER (
            PARTITION BY h.user_steps_id
            ORDER BY h.date_start_ga, h.id_ga_situation_history
        )                                                    AS fim,
        CASE WHEN LEAD(h.date_start_ga) OVER (
                     PARTITION BY h.user_steps_id
                     ORDER BY h.date_start_ga, h.id_ga_situation_history
                 ) IS NULL THEN 1 ELSE 0 END                 AS is_cauda,
        CASE WHEN LEAD(h.date_start_ga) OVER (
                     PARTITION BY h.user_steps_id
                     ORDER BY h.date_start_ga, h.id_ga_situation_history
                 ) IS NULL
                  AND h.ga_situation_id = us.gaSituationIdGaSituation
             THEN 1 ELSE 0 END                               AS is_situacao_vigente,
        CASE WHEN LEAD(h.date_start_ga) OVER (
                     PARTITION BY h.user_steps_id
                     ORDER BY h.date_start_ga, h.id_ga_situation_history
                 ) IS NULL
                  AND h.ga_situation_id <> us.gaSituationIdGaSituation
             THEN 1 ELSE 0 END                               AS is_periodo_indeterminado,
        gs_atual.[description]                               AS situacao_atual_do_caso,
        CASE WHEN LEAD(h.date_start_ga) OVER (
                     PARTITION BY h.user_steps_id
                     ORDER BY h.date_start_ga, h.id_ga_situation_history
                 ) IS NOT NULL
             THEN DATEDIFF(day, h.date_start_ga, LEAD(h.date_start_ga) OVER (
                     PARTITION BY h.user_steps_id
                     ORDER BY h.date_start_ga, h.id_ga_situation_history
                 ))
             WHEN h.ga_situation_id = us.gaSituationIdGaSituation
             THEN DATEDIFF(day, h.date_start_ga, CAST(GETDATE() AS DATE))
        END                                                  AS dias_na_situacao,
        ${dataSegura('us.date_absence')}                     AS data_afastamento
    FROM [ga_situation_history] h
    INNER JOIN [user_steps] us ON h.user_steps_id = us.id_user_steps
    INNER JOIN [employee] e ON us.employeeIdEmployee = e.id_Employee
${JOINS_PESSOA}
    LEFT  JOIN [ga_situation] gs ON h.ga_situation_id = gs.id_ga_situation
    LEFT  JOIN [ga_situation] gs_atual ON us.gaSituationIdGaSituation = gs_atual.id_ga_situation
    LEFT  JOIN [cid] c_cid ON us.cidIdCid = c_cid.id_cid
    LEFT  JOIN [absence_reason] ar ON us.absenceReasonIdAbsenceReason = ar.id_absence_reason
    WHERE h.delete_datetime IS NULL
      AND us.[delete] = 'N'
      /*{{ESCOPO}}*/
)`;

// COMO LER AS COLUNAS DE CAUDA (o problema achado na rodada 4):
//   is_cauda                  -> é a última linha do histórico do caso
//   is_situacao_vigente       -> é a última E concorda com user_steps:
//                                fim NULL significa mesmo "ainda nela"
//   is_periodo_indeterminado  -> é a última e NÃO concorda: o histórico
//                                parou de ser gravado, o caso saiu desta
//                                situação e não se sabe quando
//   dias_na_situacao          -> NULL quando indeterminado, para não
//                                contaminar médias
// Contagem em data passada (recorte estoque) sobre este dataset é
// aproximada e superestima, porque o período indeterminado fica com
// fim NULL. O Motor emite ressalva obrigatória, e filtrar
// is_periodo_indeterminado = 0 dá o limite inferior confiável.

// A data a partir da qual o histórico existe. O Motor usa isto para
// avisar quando a pergunta cai antes da cobertura.
const HISTORICO_SITUACAO_DESDE = '2025-07-01';

// ---------------------------------------------------------------------
// Série temporal do afastamento (entradas − retornos por mês).
// É a única pergunta que não é um GROUP BY sobre o prelúdio, porque
// agrega dois eventos diferentes. Preservada do fluxo atual.
// ---------------------------------------------------------------------
const TEMPLATE_SERIE_AFASTAMENTO = `, mov AS (
    SELECT FORMAT(a.data_afastamento, 'yyyy-MM') AS mes_ord,
           FORMAT(a.data_afastamento, 'MM/yyyy') AS mes,
           1 AS movimento
    FROM ds_afastamento a
    WHERE a.data_afastamento >= {{DE}} AND a.data_afastamento <= {{ATE}}
      {{FILTROS}}
    UNION ALL
    SELECT FORMAT(a.data_retorno, 'yyyy-MM') AS mes_ord,
           FORMAT(a.data_retorno, 'MM/yyyy') AS mes,
           -1 AS movimento
    FROM ds_afastamento a
    WHERE a.data_retorno IS NOT NULL
      AND a.data_retorno >= {{DE}} AND a.data_retorno <= {{ATE}}
      {{FILTROS}}
)
SELECT mes                                          AS Mes,
       SUM(CASE WHEN movimento > 0 THEN 1 ELSE 0 END) AS Novos_Afastamentos,
       SUM(CASE WHEN movimento < 0 THEN 1 ELSE 0 END) AS Retornos,
       SUM(movimento)                                 AS Variacao_Liquida,
       SUM(SUM(movimento)) OVER (ORDER BY mes_ord
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS Saldo_Acumulado
FROM mov
GROUP BY mes_ord, mes
ORDER BY mes_ord`;

