// ---------------------------------------------------------------------
// Operadores permitidos, por tipo. O validador usa isto.
// ---------------------------------------------------------------------
const OPERADORES = {
  eq:       { sql: '{col} = {v}',            aridade: 1, tipos: ['texto','inteiro','numero','data','bool'] },
  ne:       { sql: '{col} <> {v}',           aridade: 1, tipos: ['texto','inteiro','numero','data','bool'] },
  in:       { sql: '{col} IN ({v})',         aridade: 'n', tipos: ['texto','inteiro','numero'] },
  contem:   { sql: "{col} LIKE '%' + {v} + '%'", aridade: 1, tipos: ['texto'] },
  gte:      { sql: '{col} >= {v}',           aridade: 1, tipos: ['inteiro','numero','data'] },
  lte:      { sql: '{col} <= {v}',           aridade: 1, tipos: ['inteiro','numero','data'] },
  nulo:     { sql: '{col} IS NULL',          aridade: 0, tipos: ['texto','inteiro','numero','data'] },
  nao_nulo: { sql: '{col} IS NOT NULL',      aridade: 0, tipos: ['texto','inteiro','numero','data'] },
};

const PERIODOS = ['mes_atual','mes_anterior','ultimos_n_meses','ultimos_n_dias',
                  'ano_corrente','ano_anterior','mes','intervalo','historico_completo'];

const RECORTES = ['fluxo','estoque','serie'];

// ---------------------------------------------------------------------
// Prompt do Interpretador — GERADO daqui, nunca escrito à mão.
// É isto que faz "declarar um campo" bastar: o campo novo aparece no
// prompt, é aceito pelo validador e compila, numa alteração só.
// ---------------------------------------------------------------------
function gerarPromptCatalogo(cat) {
  const linhas = [];
  for (const [nome, ds] of Object.entries(cat)) {
    linhas.push(`\n### dataset "${nome}" — ${ds.rotulo}`);
    linhas.push(`Use quando: ${ds.quando_usar}`);
    // Lista TODAS as datas do dataset com o rótulo, não só a padrão. Sem
    // isto o interpretador só enxergava o default, e "quantos atestados
    // foram ENVIADOS" virava recorte por início do atestado — que é outra
    // data, e devolve zero quando o atestado é antigo e a entrega é nova.
    const datas = (ds.temporal.campos_data || [])
      .map((c) => `${c} = ${(ds.campos[c] || {}).rotulo || c}`)
      .join(' | ');
    linhas.push(`Campos de data (escolha com campo_data): ${datas}`);
    linhas.push(`Campo de data padrão (se a pergunta não indicar outro): ${ds.temporal.campo_default}. Recortes: fluxo, estoque${ds.temporal.serie ? ', serie' : ''}.`);

    const dims = [], filtros = [], numericos = [];
    for (const [c, d] of Object.entries(ds.campos)) {
      if (d.dimensao) dims.push(`${c} (${d.rotulo})`);
      if (d.ops && d.ops.length) filtros.push(`${c} [${d.tipo}] ops: ${d.ops.join('/')}`);
      if (d.tipo === 'numero' || d.tipo === 'inteiro') numericos.push(c);
    }
    linhas.push(`\nDimensões (agrupar por):\n  ${dims.join('\n  ')}`);
    linhas.push(`\nFiltráveis:\n  ${filtros.join('\n  ')}`);
    linhas.push(`\nMétricas: ${Object.entries(ds.metricas).map(([k, m]) => m.sem_campo ? k : `${k}(campo)`).join(', ')}`);
    linhas.push(`Campos numéricos para somar/mediar: ${numericos.join(', ')}`);
    const listaveis = Object.entries(ds.campos).filter(([, d]) => d.listavel).map(([c]) => c);
    if (listaveis.length) linhas.push(`Use listar_valores("${nome}", campo) antes de filtrar por: ${listaveis.join(', ')}`);
  }
  return linhas.join('\n');
}

// ---------------------------------------------------------------------
// Saída do nó
// ---------------------------------------------------------------------
const ctx = $input.first().json;

return [{
  json: Object.assign({}, ctx, {
    catalogo: CATALOGO,
    operadores: OPERADORES,
    periodos: PERIODOS,
    recortes: RECORTES,
    catalogo_prompt: gerarPromptCatalogo(CATALOGO),
    catalogo_versao: VERSAO_CATALOGO,
  }),
}];

