// =====================================================================
// Não há ramo por assunto aqui. Nenhum `if` olha para texto livre.
// Tudo o que este nó aceita está declarado no nó Catálogo.
//
// Saída:
//   { ok: true,  sql, params, spec, recorte_legivel }
//   { ok: false, erro: { codigo, mensagem, campo?, sugestoes? }, tentativa }
// =====================================================================

// Trocar para true depois de confirmar options.queryReplacement na
// versão do n8n de vocês (ver mapeamento, nota do bloco 16). Com false,
// os valores são embutidos por lit(), que é a ÚNICA porta de entrada de
// valor no SQL e valida por tipo antes de escapar.
const USAR_PARAMETROS = false;

const MAX_TENTATIVAS = 2;
const LIMITE_MAX = 500;
const RE_ALIAS = /^[A-Za-z_][A-Za-z0-9_]{0,39}$/;

// ---------------------------------------------------------------------
// Erros
// ---------------------------------------------------------------------
class ErroSpec extends Error {
  constructor(codigo, mensagem, extra) {
    super(mensagem);
    this.codigo = codigo;
    this.extra = extra || {};
  }
}
const falhar = (codigo, mensagem, extra) => { throw new ErroSpec(codigo, mensagem, extra); };

const parecidos = (alvo, lista, n) => {
  const a = String(alvo).toLowerCase();
  return lista
    .map((c) => {
      const b = c.toLowerCase();
      let score = 0;
      if (b === a) score = 100;
      else if (b.includes(a) || a.includes(b)) score = 60;
      else {
        const setA = new Set(a.split(''));
        score = b.split('').filter((ch) => setA.has(ch)).length / Math.max(b.length, a.length) * 40;
      }
      return { c, score };
    })
    .sort((x, y) => y.score - x.score)
    .slice(0, n || 5)
    .map((x) => x.c);
};

// ---------------------------------------------------------------------
// Literais: a única porta de entrada de valor no SQL
// ---------------------------------------------------------------------
function lit(valor, tipo) {
  if (valor === null || valor === undefined) falhar('valor_nulo', 'Valor ausente em um filtro.');

  if (tipo === 'inteiro') {
    const n = Number(valor);
    if (!Number.isInteger(n)) falhar('valor_invalido', `"${valor}" não é um número inteiro.`);
    return String(n);
  }
  if (tipo === 'numero') {
    const n = Number(valor);
    if (!Number.isFinite(n)) falhar('valor_invalido', `"${valor}" não é um número.`);
    return String(n);
  }
  if (tipo === 'bool') {
    const v = valor === true || valor === 1 || valor === '1' || valor === 'true' || valor === 'sim';
    return v ? '1' : '0';
  }
  if (tipo === 'data') {
    const s = String(valor).slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) falhar('valor_invalido', `Data "${valor}" fora do formato AAAA-MM-DD.`);
    return `'${s}'`;
  }
  // texto
  const s = String(valor);
  if (s.length > 200) falhar('valor_invalido', 'Valor de texto acima de 200 caracteres.');
  if (/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(s)) falhar('valor_invalido', 'Valor de texto com caractere de controle.');
  return `'${s.replace(/'/g, "''")}'`;
}

// ---------------------------------------------------------------------
// Período: aritmética em código, nunca no LLM
// ---------------------------------------------------------------------
function resolverPeriodo(periodo, agora) {
  const hoje = agora ? new Date(agora) : new Date();
  const iso = (d) => d.toISOString().slice(0, 10);
  const primeiroDia = (ano, mes) => new Date(Date.UTC(ano, mes, 1));
  const ultimoDia = (ano, mes) => new Date(Date.UTC(ano, mes + 1, 0));
  const A = hoje.getUTCFullYear();
  const M = hoje.getUTCMonth();
  const p = periodo || { tipo: 'mes_atual' };
  const t = p.tipo;

  let de, ate;
  if (t === 'mes_atual') { de = primeiroDia(A, M); ate = ultimoDia(A, M); }
  else if (t === 'mes_anterior') { de = primeiroDia(A, M - 1); ate = ultimoDia(A, M - 1); }
  else if (t === 'ultimos_n_meses') {
    const n = parseInt(p.n, 10);
    if (!Number.isInteger(n) || n < 1 || n > 60) falhar('periodo_invalido', 'ultimos_n_meses exige n entre 1 e 60.');
    de = primeiroDia(A, M - (n - 1)); ate = ultimoDia(A, M);
  }
  else if (t === 'ultimos_n_dias') {
    const n = parseInt(p.n, 10);
    if (!Number.isInteger(n) || n < 1 || n > 1830) falhar('periodo_invalido', 'ultimos_n_dias exige n entre 1 e 1830.');
    ate = new Date(Date.UTC(A, M, hoje.getUTCDate()));
    de = new Date(ate.getTime() - (n - 1) * 86400000);
  }
  else if (t === 'ano_corrente') { de = primeiroDia(A, 0); ate = ultimoDia(A, 11); }
  else if (t === 'ano_anterior') { de = primeiroDia(A - 1, 0); ate = ultimoDia(A - 1, 11); }
  else if (t === 'mes') {
    const m = /^(\d{4})-(\d{2})$/.exec(String(p.mes || ''));
    if (!m) falhar('periodo_invalido', 'periodo tipo "mes" exige mes no formato AAAA-MM.');
    const ano = +m[1], mm = +m[2] - 1;
    if (mm < 0 || mm > 11) falhar('periodo_invalido', 'Mês fora de 01-12.');
    de = primeiroDia(ano, mm); ate = ultimoDia(ano, mm);
  }
  else if (t === 'intervalo') {
    const ok = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s || ''));
    if (!ok(p.de) || !ok(p.ate)) falhar('periodo_invalido', 'periodo tipo "intervalo" exige de e ate em AAAA-MM-DD.');
    if (p.de > p.ate) falhar('periodo_invalido', 'A data inicial é posterior à final.');
    de = new Date(p.de + 'T00:00:00Z'); ate = new Date(p.ate + 'T00:00:00Z');
  }
  else if (t === 'historico_completo') { de = new Date(Date.UTC(2015, 0, 1)); ate = ultimoDia(A, M); }
  else falhar('periodo_invalido', `Tipo de período "${t}" não existe.`, { sugestoes: ['mes_atual', 'mes_anterior', 'ultimos_n_meses', 'mes', 'intervalo', 'historico_completo'] });

  // A data de referência do estoque nunca passa de hoje: é o que
  // impede "quantos afastados hoje?" de responder com data futura.
  const hojeIso = iso(hoje);
  const ateIso = iso(ate);
  return { de: iso(de), ate: ateIso, ref: ateIso > hojeIso ? hojeIso : ateIso, tipo: t, n: p.n, mes: p.mes };
}

// ---------------------------------------------------------------------
// Escopo: injetado, nunca opcional
// ---------------------------------------------------------------------
function montarEscopo(ds, contexto, filtrosSpec) {
  const empresasAutorizadas = (contexto.empresas_ids || [])
    .map((v) => String(v).trim())
    .filter((v) => /^\d+$/.test(v));

  if (!empresasAutorizadas.length) {
    falhar('escopo_ausente', 'Nenhuma empresa autorizada no contexto do gestor. Consulta bloqueada.');
  }

  // O gestor pode ESTREITAR o escopo; nunca ampliar.
  const pedidas = [];
  for (const f of filtrosSpec || []) {
    if (f.campo === 'empresa_id') {
      const vals = Array.isArray(f.valor) ? f.valor : [f.valor];
      for (const v of vals) if (/^\d+$/.test(String(v).trim())) pedidas.push(String(v).trim());
    }
  }
  const intersecao = pedidas.filter((v) => empresasAutorizadas.includes(v));
  const efetivas = intersecao.length ? intersecao : empresasAutorizadas;
  const descartadas = pedidas.filter((v) => !empresasAutorizadas.includes(v));

  const cols = ds.escopo_sql;
  const partes = [`AND ${cols.empresa} IN (${efetivas.join(', ')})`];

  // ---- exclusão por unidade sem serviço contratado
  // A contratação é por CNPJ, e a empresa contratada pode estar no
  // branch_id em vez do company_id: na FIOS, as pessoas da BLACK, GREEN
  // e RED têm company_id = 1214 (a WHITE) e o branch_id na empresa
  // delas. Filtrar só empresa deixaria as 32 pessoas da RED — que não
  // tem o serviço — dentro do consolidado, sem nenhum sinal de erro.
  //
  // É uma lista NEGATIVA de propósito: ela só ESTREITA o escopo, nas
  // duas pontas. A cláusula positiva acima continua sendo empresa, então
  // isto não abre nenhuma via nova de acesso — só fecha uma.
  //
  // Unidade sem NENHUMA linha de configuração não entra nesta lista (o
  // 7.1 não a inclui): filial operacional nunca foi contratável
  // separada, e o dado dela pertence à matriz.
  const semServico = (contexto.unidades_sem_servico_ids || [])
    .map((v) => String(v).trim())
    .filter((v) => /^\d+$/.test(v));

  if (semServico.length) {
    const lista = semServico.join(', ');
    partes.push(`AND ${cols.empresa} NOT IN (${lista})`);
    if (cols.filial) {
      partes.push(`AND (${cols.filial} IS NULL OR ${cols.filial} NOT IN (${lista}))`);
    }
  }

  // gestor_depto: o departamento é restrição de acesso, não escolha.
  let deptoForcado = null;
  if (contexto.tipo_gestor === 'gestor_depto') {
    const dep = contexto.depto_gestor || {};
    if (dep.id !== undefined && dep.id !== null && /^\d+$/.test(String(dep.id))) {
      partes.push(`AND ${cols.departamento} = ${parseInt(dep.id, 10)}`);
      deptoForcado = { por: 'id', valor: String(dep.id), nome: dep.nome || null };
    } else if (dep.nome) {
      // Mesmo departamento existe como um registro por empresa: filtra
      // por nome, já dentro do recorte de empresa acima.
      // [CONFIRMADO: bloco 7] department tem company_id, então o
      // subselect por nome fica preso às empresas autorizadas em vez de
      // depender do recorte externo.
      partes.push(`AND ${cols.departamento} IN (SELECT d_e.id FROM [department] d_e WHERE d_e.[delete] = 'N' AND d_e.company_id IN (${efetivas.join(', ')}) AND d_e.[name] = ${lit(dep.nome, 'texto')})`);
      deptoForcado = { por: 'nome', valor: dep.nome, nome: dep.nome };
    } else {
      falhar('escopo_ausente', 'Gestor de departamento sem departamento definido no contexto. Consulta bloqueada.');
    }
  }

  return {
    sql: partes.join('\n      '),
    empresas: efetivas,
    descartadas,
    deptoForcado,
    unidadesExcluidas: semServico,
  };
}

// ---------------------------------------------------------------------
// Validação do spec
// ---------------------------------------------------------------------
function validarSpec(spec, bundle) {
  const cat = bundle.catalogo, ops = bundle.operadores;

  if (!spec || typeof spec !== 'object') falhar('spec_invalido', 'O interpretador não devolveu um objeto JSON.');

  const nomeDs = spec.dataset;
  if (!cat[nomeDs]) {
    falhar('dataset_invalido', `Dataset "${nomeDs}" não existe.`, { sugestoes: Object.keys(cat) });
  }
  const ds = cat[nomeDs];

  const modo = spec.modo || 'agregado';
  if (modo !== 'agregado' && modo !== 'detalhe') {
    falhar('modo_invalido', `modo deve ser "agregado" ou "detalhe" (recebi "${modo}").`);
  }

  const recorte = spec.recorte || 'fluxo';
  if (!bundle.recortes.includes(recorte)) {
    falhar('recorte_invalido', `recorte "${recorte}" não existe.`, { sugestoes: bundle.recortes });
  }
  if (recorte === 'serie' && !ds.temporal.serie) {
    falhar('recorte_indisponivel',
      `O dataset "${nomeDs}" não tem série temporal. Use recorte "fluxo" com a dimensão "mes".`);
  }

  const campoData = spec.campo_data || ds.temporal.campo_default;
  if (!ds.temporal.campos_data.includes(campoData)) {
    falhar('campo_data_invalido', `campo_data "${campoData}" não serve para recorte temporal em "${nomeDs}".`,
      { sugestoes: ds.temporal.campos_data });
  }

  // dimensões
  const dimensoes = Array.isArray(spec.dimensoes) ? spec.dimensoes : [];
  if (dimensoes.length > 3) falhar('dimensoes_demais', 'No máximo 3 dimensões por consulta.');
  for (const d of dimensoes) {
    const def = ds.campos[d];
    if (!def) falhar('campo_inexistente', `O campo "${d}" não existe no dataset "${nomeDs}".`,
      { campo: d, sugestoes: parecidos(d, Object.entries(ds.campos).filter(([, x]) => x.dimensao).map(([k]) => k)) });
    if (!def.dimensao) falhar('campo_nao_dimensao', `"${d}" não pode ser usado para agrupar.`,
      { campo: d, sugestoes: Object.entries(ds.campos).filter(([, x]) => x.dimensao).map(([k]) => k).slice(0, 8) });
  }

  // métricas
  let metricas = Array.isArray(spec.metricas) ? spec.metricas : [];
  if (modo === 'agregado') {
    if (!metricas.length) {
      metricas = [{ fn: 'contar_distinto', campo: ds.chave.split('.')[1], como: 'Quantidade' }];
    }
    const vistos = new Set();
    for (const m of metricas) {
      const def = ds.metricas[m.fn];
      if (!def) falhar('metrica_inexistente', `A métrica "${m.fn}" não existe.`,
        { sugestoes: Object.keys(ds.metricas) });
      if (!def.sem_campo) {
        if (!m.campo) falhar('metrica_sem_campo', `A métrica "${m.fn}" exige um campo.`);
        const cdef = ds.campos[m.campo];
        if (!cdef) falhar('campo_inexistente', `O campo "${m.campo}" não existe no dataset "${nomeDs}".`,
          { campo: m.campo, sugestoes: parecidos(m.campo, Object.keys(ds.campos)) });
        if ((m.fn === 'somar' || m.fn === 'media') && cdef.tipo !== 'numero' && cdef.tipo !== 'inteiro') {
          falhar('metrica_tipo_incompativel',
            `"${m.fn}" só funciona em campo numérico; "${m.campo}" é ${cdef.tipo}.`,
            { campo: m.campo, sugestoes: Object.entries(ds.campos).filter(([, x]) => x.tipo === 'numero').map(([k]) => k) });
        }
      }
      m.como = m.como || (def.sem_campo ? m.fn : `${m.fn}_${m.campo}`);
      if (!RE_ALIAS.test(m.como)) falhar('alias_invalido', `O rótulo "${m.como}" tem caractere não permitido.`);
      if (vistos.has(m.como)) falhar('alias_duplicado', `Dois resultados com o mesmo rótulo "${m.como}".`);
      vistos.add(m.como);
    }
  } else {
    metricas = [];
  }

  // Campos marcados como sensíveis (hoje: is_pcd) só podem ser usados
  // em consulta AGREGADA. Em modo detalhe eles produziriam uma lista
  // nominal de pessoas por atributo protegido, que é exatamente o que
  // um painel de RH não deve gerar.
  if (modo === 'detalhe') {
    const usadosDet = [...dimensoes, ...(Array.isArray(spec.filtros) ? spec.filtros.map((f) => f.campo) : [])];
    const sens = usadosDet.filter((c) => ds.campos[c] && ds.campos[c].sensivel);
    if (sens.length) {
      falhar('campo_sensivel_em_lista',
        `${sens.join(', ')} não pode ser usado em consulta nominal: geraria uma lista de pessoas por atributo protegido.`,
        { sugestoes: ['use modo "agregado" para ter o número, sem os nomes'] });
    }
  }

  // filtros
  const filtros = Array.isArray(spec.filtros) ? spec.filtros : [];
  for (const f of filtros) {
    const def = ds.campos[f.campo];
    if (!def) falhar('campo_inexistente', `O campo "${f.campo}" não existe no dataset "${nomeDs}".`,
      { campo: f.campo, sugestoes: parecidos(f.campo, Object.keys(ds.campos)) });
    const op = ops[f.op];
    if (!op) falhar('operador_inexistente', `O operador "${f.op}" não existe.`, { sugestoes: Object.keys(ops) });
    if (!def.ops.includes(f.op)) falhar('operador_nao_permitido',
      `O operador "${f.op}" não vale para "${f.campo}".`, { campo: f.campo, sugestoes: def.ops });
    if (!op.tipos.includes(def.tipo)) falhar('operador_tipo_incompativel',
      `O operador "${f.op}" não se aplica a campo do tipo ${def.tipo}.`, { campo: f.campo, sugestoes: def.ops });
    if (op.aridade === 0 && f.valor !== undefined && f.valor !== null) {
      falhar('valor_inesperado', `O operador "${f.op}" não leva valor.`);
    }
    if (op.aridade === 1 && (f.valor === undefined || f.valor === null || Array.isArray(f.valor))) {
      falhar('valor_invalido', `O operador "${f.op}" exige um valor único em "${f.campo}".`);
    }
    if (op.aridade === 'n') {
      if (!Array.isArray(f.valor) || !f.valor.length) falhar('valor_invalido', `O operador "in" exige uma lista não vazia em "${f.campo}".`);
      if (f.valor.length > 50) falhar('valor_invalido', 'Lista de valores acima de 50 itens.');
    }
  }

  // ordem
  const ordem = Array.isArray(spec.ordem) ? spec.ordem : [];
  const rotulosValidos = new Set([...metricas.map((m) => m.como), ...dimensoes]);
  for (const o of ordem) {
    if (!rotulosValidos.has(o.por)) falhar('ordem_invalida',
      `Não posso ordenar por "${o.por}": ordene por uma métrica ou dimensão da própria consulta.`,
      { sugestoes: [...rotulosValidos] });
    if (o.dir && o.dir !== 'asc' && o.dir !== 'desc') falhar('ordem_invalida', 'dir deve ser "asc" ou "desc".');
  }

  let limite = spec.limite === undefined ? 100 : parseInt(spec.limite, 10);
  if (!Number.isInteger(limite) || limite < 1) falhar('limite_invalido', 'limite deve ser inteiro >= 1.');
  if (limite > LIMITE_MAX) limite = LIMITE_MAX;

  // Campos de estado ATUAL (situacao, etapa, is_limbo...) descrevem
  // como o afastamento está agora, não como estava numa data passada.
  // Isso não invalida a consulta — "dos que começaram em março, quantos
  // estão em limbo hoje?" é legítimo — mas a resposta tem de dizer isso,
  // em vez de deixar o gestor achar que é um retrato do passado.
  const usados = [...dimensoes, ...filtros.map((f) => f.campo)];
  const estados = [...new Set(usados.filter((c) => ds.campos[c] && ds.campos[c].estado_atual))];

  // O período é resolvido AQUI para falhar cedo (o erro volta ao
  // interpretador com sugestão) e é propagado no spec normalizado.
  // Não propagar era um bug: compilar() recebia undefined e toda
  // consulta caía no default mes_atual, descartando em silêncio o
  // período que o interpretador havia pedido.
  const periodo = spec.periodo === undefined ? { tipo: 'mes_atual' } : spec.periodo;
  if (periodo === null || typeof periodo !== 'object' || Array.isArray(periodo)) {
    falhar('periodo_invalido', 'periodo deve ser um objeto com { tipo: ... }.',
      { sugestoes: bundle.periodos });
  }
  if (!bundle.periodos.includes(periodo.tipo)) {
    falhar('periodo_invalido', `Tipo de período "${periodo.tipo}" não existe.`,
      { sugestoes: bundle.periodos });
  }

  return { dataset: nomeDs, modo, recorte, campo_data: campoData, periodo,
           dimensoes, metricas, filtros, ordem, limite,
           campos_estado_atual: estados,
           explicacao: typeof spec.explicacao === 'string' ? spec.explicacao.slice(0, 600) : '' };
}

// ---------------------------------------------------------------------
// Compilação
// ---------------------------------------------------------------------
function compilar(spec, bundle, contexto, agora) {
  const ds = bundle.catalogo[spec.dataset];
  const ops = bundle.operadores;
  const alias = ds.alias;
  const nomeDs = 'ds_' + spec.dataset;
  const params = [];

  const V = (valor, tipo) => {
    if (USAR_PARAMETROS) { params.push(valor); return '?'; }
    return lit(valor, tipo);
  };

  const periodo = resolverPeriodo(spec.periodo, agora);
  const escopo = montarEscopo(ds, contexto, spec.filtros);
  const prelude = ds.prelude.replace('/*{{ESCOPO}}*/', escopo.sql);

  // --- predicado temporal
  const colData = ds.campos[spec.campo_data].sql;
  let predTemporal;
  if (spec.recorte === 'estoque') {
    const est = ds.temporal.estoque;
    predTemporal = `${est.inicio} <= ${V(periodo.ref, 'data')} AND (${est.fim} IS NULL OR ${est.fim} > ${V(periodo.ref, 'data')})`;
  } else if (periodo.tipo === 'historico_completo') {
    predTemporal = '1 = 1';
  } else {
    predTemporal = `${colData} >= ${V(periodo.de, 'data')} AND ${colData} <= ${V(periodo.ate, 'data')}`;
  }

  // --- filtros (o de escopo em empresa_id já entrou no prelúdio)
  const condicoes = [];
  const ignorados = [];
  for (const f of spec.filtros) {
    if (f.campo === 'empresa_id') continue;
    if (escopo.deptoForcado && (f.campo === 'departamento' || f.campo === 'departamento_id')) {
      // O gestor pediu um departamento que não é o dele. Não dá erro:
      // responde o departamento autorizado E registra o descarte, para
      // a Mindy poder dizer isso na resposta em vez de fingir.
      ignorados.push({ campo: f.campo, valor: f.valor, motivo: 'restricao_de_acesso_departamento' });
      continue;
    }
    const def = ds.campos[f.campo];
    const op = ops[f.op];
    let sql;
    if (op.aridade === 0) sql = op.sql.replace('{col}', def.sql);
    else if (op.aridade === 'n') sql = op.sql.replace('{col}', def.sql).replace('{v}', f.valor.map((v) => V(v, def.tipo)).join(', '));
    else sql = op.sql.replace('{col}', def.sql).replace(/\{v\}/g, V(f.valor, def.tipo));
    condicoes.push(sql);
  }
  const filtrosSql = condicoes.length ? '\n      AND ' + condicoes.join('\n      AND ') : '';

  // --- caminho 2: série temporal
  if (spec.recorte === 'serie') {
    const corpo = ds.temporal.serie
      .replace(/\{\{DE\}\}/g, V(periodo.de, 'data'))
      .replace(/\{\{ATE\}\}/g, V(periodo.ate, 'data'))
      .replace(/\{\{FILTROS\}\}/g, filtrosSql);
    return { sql: `WITH ${prelude}${corpo}`, params, periodo, escopo, ignorados };
  }

  // --- caminho 1: agregado ou detalhe
  let selects = [], groupBy = [], orderBy = [];

  if (spec.modo === 'detalhe') {
    for (const col of ds.detalhe) {
      const def = ds.campos[col.campo];
      if (def) selects.push(`${def.sql} AS ${col.como}`);
    }
    // dimensões pedidas que não estão no detalhe padrão entram também
    for (const d of spec.dimensoes) {
      if (!ds.detalhe.some((x) => x.campo === d)) selects.push(`${ds.campos[d].sql} AS ${d}`);
    }
    orderBy = spec.ordem.length
      ? spec.ordem.map((o) => `${o.por} ${o.dir === 'asc' ? 'ASC' : 'DESC'}`)
      : [`${ds.campos.colaborador ? ds.campos.colaborador.sql : selects[0].split(' AS ')[0]} ASC`];
  } else {
    for (const d of spec.dimensoes) {
      const def = ds.campos[d];
      selects.push(`${def.sql} AS ${d}`);
      groupBy.push(def.sql);
      if (def.sql_ord) groupBy.push(def.sql_ord);
    }
    for (const m of spec.metricas) {
      const def = ds.metricas[m.fn];
      const expr = def.sem_campo ? def.sql : def.sql.replace('{campo}', ds.campos[m.campo].sql);
      selects.push(`${expr} AS ${m.como}`);
    }
    if (spec.ordem.length) {
      orderBy = spec.ordem.map((o) => `${o.por} ${o.dir === 'asc' ? 'ASC' : 'DESC'}`);
    } else if (spec.metricas.length && spec.dimensoes.length) {
      orderBy = [`${spec.metricas[0].como} DESC`];
    } else if (spec.dimensoes.length) {
      const d0 = ds.campos[spec.dimensoes[0]];
      orderBy = [`${d0.sql_ord || d0.sql} ASC`];
    }
    // ordenar por mês é cronológico, nunca alfabético
    const dimMes = spec.dimensoes.find((d) => ds.campos[d].sql_ord);
    if (dimMes && !spec.ordem.length) {
      orderBy = [`${ds.campos[dimMes].sql_ord} ASC`];
    }
  }

  const partes = [
    `WITH ${prelude}`,
    `SELECT TOP (${spec.limite}) ${selects.join(',\n       ')}`,
    `FROM ${nomeDs} ${alias}`,
    `WHERE ${predTemporal}${filtrosSql}`,
  ];
  if (groupBy.length) partes.push(`GROUP BY ${[...new Set(groupBy)].join(', ')}`);
  if (orderBy.length) partes.push(`ORDER BY ${orderBy.join(', ')}`);

  return { sql: partes.join('\n'), params, periodo, escopo, ignorados };
}

// ---------------------------------------------------------------------
// Validação da SQL final — invariantes verificados, não lembrados.
// No caminho compilado é redundante por construção: serve de rede
// contra bug no compilador. No fallback, é essencial.
// ---------------------------------------------------------------------
// Atenção: o esquema da BMS usa "delete" como NOME DE COLUNA
// (us.[delete] = 'N'). Por isso o teste é feito depois de remover
// identificadores entre colchetes, e exige a palavra em posição de
// comando (DELETE FROM, DROP <algo>...), não a palavra solta.
const PROIBIDO = new RegExp(
  '\\b(' +
  'INSERT\\s+INTO|UPDATE\\s+[A-Za-z_]|DELETE\\s+FROM|MERGE\\s+INTO|' +
  'DROP\\s+[A-Za-z_]|ALTER\\s+[A-Za-z_]|CREATE\\s+[A-Za-z_]|TRUNCATE\\s+TABLE|' +
  'GRANT\\s+[A-Za-z_]|REVOKE\\s+[A-Za-z_]|EXEC\\s|EXECUTE\\s|SHUTDOWN|' +
  'BACKUP\\s+[A-Za-z_]|RESTORE\\s+[A-Za-z_]|OPENROWSET|OPENDATASOURCE|OPENQUERY|' +
  'WAITFOR\\s+DELAY' +
  ')|xp_[a-z]|sp_configure|sp_executesql', 'i');

function validarSql(sql, opcoes) {
  const o = opcoes || {};
  const erros = [];

  if (typeof sql !== 'string' || !sql.trim()) return ['SQL vazia.'];

  // 1) neutraliza literais de string  2) neutraliza [identificadores]
  // Mantém o NOME dentro dos colchetes (para a mensagem de erro dizer
  // qual tabela foi tocada), mas tira os colchetes, que é o que fazia
  // us.[delete] casar com \bDELETE\b.
  const semLiterais = sql
    .replace(/'(?:[^']|'')*'/g, "''")
    .replace(/\[([^\]\n]*)\]/g, '$1');

  if (/;/.test(semLiterais)) erros.push('SQL com ";": só um comando por consulta.');
  if (!/^\s*WITH\s+ds_/i.test(sql)) erros.push('SQL deve começar com "WITH ds_<dataset>".');
  if (PROIBIDO.test(semLiterais)) erros.push('SQL contém comando não permitido (só SELECT é aceito).');
  if (!/\bTOP\s*\(?\s*\d+/i.test(semLiterais)) erros.push('SQL sem TOP: toda consulta precisa de limite.');

  // toda origem de dados do corpo externo tem de ser um ds_*
  const corpo = semLiterais.slice(o.fimPrelude !== undefined ? o.fimPrelude : indiceFimPrelude(semLiterais));
  const origens = [...corpo.matchAll(/\b(?:FROM|JOIN)\s+(\[?[A-Za-z_][A-Za-z0-9_]*\]?)/gi)].map((m) => m[1].replace(/[\[\]]/g, ''));
  for (const t of origens) {
    if (!/^ds_/.test(t) && !(o.cteExtras || ['mov']).includes(t)) {
      erros.push(`A consulta acessa "${t}" diretamente; só os datasets ds_* são permitidos.`);
    }
  }

  // o escopo tem de estar no prelúdio
  if (!/IN\s*\(\s*\d+(\s*,\s*\d+)*\s*\)/.test(semLiterais) && !/\?/.test(semLiterais)) {
    erros.push('Não encontrei o predicado de escopo por empresa no prelúdio.');
  }

  if (semLiterais.length > 60000) erros.push('SQL absurdamente longa.');
  return erros;
}

function indiceFimPrelude(sql) {
  // fim do bloco WITH: primeiro ")" de profundidade 0 seguido de SELECT
  let prof = 0;
  for (let i = 0; i < sql.length; i++) {
    const c = sql[i];
    if (c === '(') prof++;
    else if (c === ')') {
      prof--;
      if (prof === 0) {
        const resto = sql.slice(i + 1);
        const m = /^\s*(,|SELECT)/i.exec(resto);
        if (m && m[1].toUpperCase() === 'SELECT') return i + 1;
      }
    }
  }
  return 0;
}

// ---------------------------------------------------------------------
// Orquestração do nó
// ---------------------------------------------------------------------
function parseSpec(bruto) {
  if (bruto && typeof bruto === 'object') return bruto;
  let s = String(bruto || '').trim();
  const cerca = s.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (cerca) s = cerca[1].trim();
  else {
    const chaves = s.match(/\{[\s\S]*\}/);
    if (chaves) s = chaves[0];
  }
  try { return JSON.parse(s); }
  catch (e) { falhar('spec_invalido', 'O interpretador não devolveu JSON válido.'); }
}

function motor(specBruto, bundle, contexto, tentativa, agora) {
  try {
    const spec = validarSpec(parseSpec(specBruto), bundle);
    const c = compilar(spec, bundle, contexto, agora);
    const erros = validarSql(c.sql, { cteExtras: ['mov'] });
    if (erros.length) falhar('sql_invalida', erros.join(' | '));

    const ds = bundle.catalogo[spec.dataset];

    // Duas listas, e a diferença é quem pode ler:
    //
    //   ressalvas          -> vão para a Mindy e podem chegar ao gestor.
    //                         Falam do RECORTE da resposta ("este número é
    //                         a situação de hoje, não a do período"), que é
    //                         informação que o gestor precisa para não ler
    //                         o número errado.
    //
    //   ressalvas_internas -> NUNCA chegam ao gestor. Falam do estado dos
    //                         dados da BMS. O cliente não quer — e com
    //                         razão: "o histórico não foi gravado" é um
    //                         problema nosso e do fornecedor, não do
    //                         gestor de RH, e dizer isso na resposta só
    //                         faz ele desconfiar do número inteiro.
    //                         Ficam no bloco _diag, para o log e para a
    //                         conversa com a BMS.
    const ressalvas = [];
    const ressalvasInternas = [];
    if (spec.campos_estado_atual.length && spec.recorte !== 'estoque') {
      const rotulos = spec.campos_estado_atual.map((c) => ds.campos[c].rotulo.split(' (')[0]);
      ressalvas.push(
        `${rotulos.join(' e ')} ${rotulos.length > 1 ? 'refletem' : 'reflete'} a situação de HOJE, ` +
        `não a do período consultado: o recorte de data se aplica ao início do afastamento. ` +
        `Para situação numa data passada existe o dataset "situacao_periodo".`);
    }
    if (spec.campos_estado_atual.length && spec.recorte === 'serie') {
      ressalvas.push('Série temporal com filtro de situação atual mede quando os casos começaram, não quando entraram nessa situação.');
    }

    if (spec.dataset === 'situacao_periodo' && spec.recorte === 'estoque'
        && !spec.filtros.some((f) => f.campo === 'is_periodo_indeterminado')) {
      // INTERNA. Não vai para a resposta.
      ressalvasInternas.push(
        'APROXIMACAO_CAUDA_HISTORICO: em parte dos casos a última transição não foi ' +
        'gravada (a última linha do histórico diz uma situação e o cadastro atual diz ' +
        'outra), então não se sabe quando o período terminou e esta contagem em data ' +
        'passada tende a superestimar. Para medir só os casos determinados, filtre ' +
        'is_periodo_indeterminado = 0.');
    }

    if (ds.cobertura_desde) {
      const limite = ds.cobertura_desde;
      if (c.periodo.de < limite) {
        const br = limite.split('-').reverse().join('/');
        // Esta FICA visível, e de propósito. Não é defeito de dado: é o
        // alcance do que existe. Suprimir faria o gestor pedir "março de
        // 2025" e receber um número parcial acreditando ser o total —
        // erro de leitura pior que a ressalva. Redigida sem falar de
        // gravação, transição ou inconsistência: só o alcance.
        ressalvas.push(
          `Os dados disponíveis para este tipo de análise começam em ${br}. ` +
          `O período pedido é anterior a isso, então a resposta cobre a partir de ${br}.`);
      }
      if (c.periodo.ate < limite) {
        falhar('fora_da_cobertura',
          `Os dados disponíveis para este tipo de análise começam em ${limite.split('-').reverse().join('/')}. O período pedido termina antes disso.`,
          { sugestoes: ['use o dataset "afastamento" para a situação atual',
                        'ou peça um período a partir de 07/2025'] });
      }
    }

    // O rótulo do recorte diz TAMBÉM por qual data o período foi aplicado.
    // Sem isso, "atestados nos últimos 6 meses" por data de entrega e por
    // período de afastamento produzem respostas idênticas na aparência e
    // números diferentes — e o gestor não tem como perceber a troca.
    const rotuloData = (ds.campos[spec.campo_data] || {}).rotulo || spec.campo_data;
    const temVariasDatas = (ds.temporal.campos_data || []).length > 1;
    const sufixoData = (temVariasDatas && spec.recorte !== 'estoque')
      ? ` — por ${rotuloData.toLowerCase()}` : '';

    const recorteLegivel = spec.recorte === 'estoque'
      ? `situação em ${c.periodo.ref.split('-').reverse().join('/')}`
      : `${c.periodo.de.split('-').reverse().join('/')} a ${c.periodo.ate.split('-').reverse().join('/')}${sufixoData}`;

    return {
      ok: true,
      sql: c.sql,
      params: c.params,
      usar_parametros: USAR_PARAMETROS,
      spec,
      dataset_rotulo: ds.rotulo,
      periodo: c.periodo,
      recorte_legivel: recorteLegivel,
      campo_data: spec.campo_data,
      campo_data_rotulo: rotuloData,
      ressalvas,
      ressalvas_internas: ressalvasInternas,
      escopo: { empresas: c.escopo.empresas, empresas_descartadas: c.escopo.descartadas, departamento: c.escopo.deptoForcado },
      filtros_legiveis: spec.filtros
        .filter((f) => f.campo !== 'empresa_id')
        .map((f) => ({ rotulo: (ds.campos[f.campo] || {}).rotulo || f.campo, op: f.op, valor: f.valor })),
      filtros_ignorados: (c.ignorados || []).map((f) => ({
        rotulo: (ds.campos[f.campo] || {}).rotulo || f.campo, valor: f.valor, motivo: f.motivo })),
      tentativa: tentativa || 1,
    };
  } catch (e) {
    const codigo = e instanceof ErroSpec ? e.codigo : 'erro_interno';
    return {
      ok: false,
      erro: Object.assign({ codigo, mensagem: e.message }, (e.extra || {})),
      tentativa: tentativa || 1,
      esgotou: (tentativa || 1) >= MAX_TENTATIVAS,
    };
  }
}

// ---------------------------------------------------------------------
const bundleNode = $('Catálogo').first().json;
const ctx = $('Contexto do gestor').first().json;
const entrada = $input.first().json;

const bundle = {
  catalogo: bundleNode.catalogo,
  operadores: bundleNode.operadores,
  periodos: bundleNode.periodos,
  recortes: bundleNode.recortes,
};

// O agente devolve em "output". Numa nova tentativa, o item já traz
// "tentativa" para o contador não reiniciar.
const specBruto = entrada.output !== undefined ? entrada.output : entrada.spec;
const tentativa = entrada.tentativa || 1;

const r = motor(specBruto, bundle, ctx, tentativa, ctx.agora);

return [{
  json: Object.assign({
    pergunta: ctx.pergunta,
    chat_id: ctx.chat_id,
    catalogo_versao: bundleNode.catalogo_versao,
  }, r),
}];

// =====================================================================
// NÓ "Preparar nova tentativa"
// =====================================================================
// Recebe erro de validação/compilação OU erro do banco e monta a
// instrução de correção. Devolve o MESMO formato do nó Catálogo, para o
// Interpretador poder ser reaproveitado sem prompt diferente.
// =====================================================================

const MAX_TENTATIVAS = 2;

const cat = $('Catálogo').first().json;
const ctx = $('Contexto do gestor').first().json;
const item = $input.first().json;

const tentativa = (item.tentativa || 1) + 1;

let instrucao;
if (item.erro) {
  const e = item.erro;
  const sug = e.sugestoes && e.sugestoes.length
    ? `\nOpções válidas: ${e.sugestoes.join(', ')}.`
    : '';
  instrucao =
    `A consulta anterior foi RECUSADA na validação.\n` +
    `Motivo (${e.codigo}): ${e.mensagem}${sug}\n` +
    `Corrija o spec e devolva um spec COMPLETO novo. Não repita o mesmo campo ou operador recusado.`;
} else {
  // erro vindo do nó de banco
  const msg = (item.error && (item.error.message || item.error.description))
    || item.message || 'Erro não identificado no banco.';
  instrucao =
    `O banco recusou a consulta gerada.\n` +
    `Mensagem: ${String(msg).slice(0, 500)}\n` +
    `Simplifique o spec: menos dimensões, período mais curto, ou métrica mais simples.`;
}

return [{
  json: Object.assign({}, cat, {
    tentativa,
    esgotou: tentativa > MAX_TENTATIVAS,
    instrucao_retry: instrucao,
    spec_anterior: item.spec ? JSON.stringify(item.spec) : null,
    erro_anterior: item.erro || null,
  }),
}];

// =====================================================================
// NÓ "Validar SQL do fallback"
// =====================================================================
// O agente do fallback escreve SELECT sobre os nomes ds_*. O prelúdio
// (COM o predicado de escopo) é prependido AQUI, por código. É isso que
// torna o caminho livre seguro: o modelo não alcança as tabelas físicas,
// só o dataset já recortado.
