  const origens = [...corpo.matchAll(/\b(?:FROM|JOIN)\s+(\[?[A-Za-z_][A-Za-z0-9_]*\]?)/gi)].map((m) => m[1].replace(/[\[\]]/g, ''));
  for (const t of origens) {
    if (!/^ds_/.test(t) && !(o.cteExtras || ['mov']).includes(t)) {
