  if (/;/.test(semLiterais)) erros.push('SQL com ";": só um comando por consulta.');
  if (!/^\s*WITH\s+ds_/i.test(sql)) erros.push('SQL deve começar com "WITH ds_<dataset>".');
  if (PROIBIDO.test(semLiterais)) erros.push('SQL contém comando não permitido (só SELECT é aceito).');
  if (!/\bTOP\s*\(?\s*\d+/i.test(semLiterais)) erros.push('SQL sem TOP: toda consulta precisa de limite.');

  // toda origem de dados do corpo externo tem de ser um ds_*
  const corpo = semLiterais.slice(o.fimPrelude !== undefined ? o.fimPrelude : indiceFimPrelude(semLiterais));
  const origens = [...corpo.matchAll(/\b(?:FROM|JOIN)\s+(\[?[A-Za-z_][A-Za-z0-9_]*\]?)/gi)].map((m) => m[1].replace(/[\[\]]/g, ''));
