function indiceFimPrelude(sql) {
  // fim do bloco WITH: primeiro ")" de profundidade 0 seguido de SELECT
  let prof = 0;
  for (let i = 0; i < sql.length; i++) {
    const c = sql[i];
    if (c === '(') prof++;
    else if (c === ')') {
      prof--;
      if (prof === 0) {
        const resto = sql.slice(i + 1);
        const m = /^\s*(,|SELECT)/i.exec(resto);
        if (m && m[1].toUpperCase() === 'SELECT') return i + 1;
      }
    }
  }
  return 0;
}


const cat = $('Catálogo').first().json;
const ctx = $('Contexto do gestor').first().json;
const item = $input.first().json;

let bruto = item.output !== undefined ? item.output : item.sql;
if (bruto && typeof bruto === 'object') bruto = bruto.sql || JSON.stringify(bruto);
let corpo = String(bruto || '').trim();

// tira cercas de código, se vierem
const cerca = corpo.match(/```(?:sql)?\s*([\s\S]*?)\s*```/i);
if (cerca) corpo = cerca[1].trim();
corpo = corpo.replace(/;+\s*$/, '').trim();

// qual dataset o fallback usou?
const usados = [...corpo.matchAll(/\bds_([a-z_]+)\b/gi)].map((m) => 'ds_' + m[1].toLowerCase());
const nomes = [...new Set(usados)];

if (!nomes.length) {
  return [{ json: { ok: false, erro: 'O fallback não referenciou nenhum dataset ds_*.' } }];
}

// monta o prelúdio de cada dataset citado, com escopo
const empresas = ctx.empresas_ids.filter((v) => /^\d+$/.test(String(v)));
if (!empresas.length) return [{ json: { ok: false, erro: 'Sem empresa autorizada.' } }];

const preludios = [];
for (const nome of nomes) {
  const chave = nome.replace(/^ds_/, '');
  const ds = cat.catalogo[chave];
  if (!ds) return [{ json: { ok: false, erro: `O fallback citou "${nome}", que não é um dataset válido.` } }];

  const partes = [`AND ${ds.escopo_sql.empresa} IN (${empresas.join(', ')})`];
  if (ctx.tipo_gestor === 'gestor_depto') {
    const dep = ctx.depto_gestor || {};
    if (dep.id && /^\d+$/.test(String(dep.id))) {
      partes.push(`AND ${ds.escopo_sql.departamento} = ${parseInt(dep.id, 10)}`);
    } else if (dep.nome) {
      const nomeEsc = String(dep.nome).replace(/'/g, "''");
      partes.push(`AND ${ds.escopo_sql.departamento} IN (SELECT d_e.id FROM [department] d_e WHERE d_e.[delete] = 'N' AND d_e.[name] = '${nomeEsc}')`);
    } else {
      return [{ json: { ok: false, erro: 'Gestor de departamento sem departamento definido.' } }];
    }
  }
  preludios.push(ds.prelude.replace('/*{{ESCOPO}}*/', partes.join('\n      ')));
}

// TOP obrigatório
if (!/\bTOP\s*\(?\s*\d+/i.test(corpo)) {
  corpo = corpo.replace(/^\s*SELECT\s+(DISTINCT\s+)?/i, (m, d) => `SELECT ${d || ''}TOP (200) `);
}

const sql = `WITH ${preludios.join(',\n')}\n${corpo}`;
const erros = validarSql(sql, { cteExtras: [] });

return [{
  json: erros.length
    ? { ok: false, erro: erros.join(' | '), sql }
    : { ok: true, sql, params: [], usar_parametros: false, datasets: nomes,
        explicacao: 'Consulta livre validada sobre os datasets ' + nomes.join(', ') + '.',
        recorte_legivel: 'definido pela própria consulta' },
}];

// =====================================================================
// NÓ "Consolidar resultado"
// =====================================================================
// Normaliza o que veio do banco (caminho compilado OU fallback) num
// formato único para a Mindy. É aqui que "zero linhas" deixa de ser
// indistinguível de "erro".
// =====================================================================

const linhas = $input.all().map((i) => i.json).filter((j) => j && Object.keys(j).length);

// De qual caminho veio?
let origem = 'compilado', motor = null;
try { motor = $('Motor de consulta').first().json; } catch (e) { motor = null; }
let fallback = null;
try { fallback = $('Validar SQL do fallback').first().json; } catch (e) { fallback = null; }
if (fallback && fallback.ok && !(motor && motor.ok)) origem = 'fallback';

const ctx = $('Contexto do gestor').first().json;
const base = (origem === 'compilado' && motor && motor.ok) ? motor : null;

// Rótulos legíveis: a Mindy recebe estrutura, não precisa reconstruir
// nada lendo prosa.
const descricao = base ? {
  dataset: base.spec ? base.spec.dataset : base.dataset_rotulo,
  dataset_rotulo: base.dataset_rotulo,
  recorte: base.recorte_legivel,
  campo_data: base.campo_data || null,
  campo_data_rotulo: base.campo_data_rotulo || null,
  recorte_tipo: base.spec ? base.spec.recorte : null,
  periodo: base.periodo ? { de: base.periodo.de, ate: base.periodo.ate, ref: base.periodo.ref, tipo: base.periodo.tipo } : null,
  filtros: base.filtros_legiveis || [],
  filtros_ignorados: base.filtros_ignorados || [],
  escopo_departamento: base.escopo && base.escopo.departamento ? base.escopo.departamento.nome : null,
  ressalvas: base.ressalvas || [],
  // Nunca vão para a Mindy: ficam só no _diag, para o log e para a
  // conversa com a BMS. Falar do estado do banco com o gestor de RH é
  // ruído que faz ele duvidar do número certo.
  ressalvas_internas: base.ressalvas_internas || [],
  empresas_descartadas: base.escopo ? base.escopo.empresas_descartadas : [],
  consolidado: ctx.consolidado,
  metricas: base.spec ? base.spec.metricas.map((m) => m.como) : [],
  dimensoes: base.spec ? base.spec.dimensoes : [],
  modo: base.spec ? base.spec.modo : null,
  explicacao: base.spec ? base.spec.explicacao : '',
} : {
  dataset: 'consulta livre (fallback)',
  recorte: (fallback && fallback.recorte_legivel) || 'não informado',
  campo_data: null, campo_data_rotulo: null,
  recorte_tipo: null, periodo: null,
  filtros: [], filtros_ignorados: [], escopo_departamento: null,
  empresas_descartadas: [], consolidado: ctx.consolidado, ressalvas: [], ressalvas_internas: [],
  metricas: [], dimensoes: [], modo: 'fallback',
  explicacao: (fallback && fallback.explicacao) || '',
};

return [{
  json: {
    pergunta: ctx.pergunta,
    chat_id: ctx.chat_id,
    origem,
    tentativas: (motor && motor.tentativa) || 1,
    catalogo_versao: (motor && motor.catalogo_versao) || null,
    vazio: linhas.length === 0,
    qtd_linhas: linhas.length,
    linhas: linhas.slice(0, 50),
    descricao,
    sql: base ? base.sql : (fallback ? fallback.sql : null),
  },
}];

// =====================================================================
// NÓ "Decidir gráfico"
// =====================================================================
// Decisão determinística. Saiu do prompt da Mindy: ela redige, o código
// decide. Mesmo resultado sempre, para o mesmo formato de dado.
// =====================================================================

const cons = $('Consolidar resultado').first().json;
const mindy = $input.first().json;

// A resposta da Mindy pode vir como texto puro ou como JSON em cerca.
let resposta = mindy.output !== undefined ? mindy.output : (mindy.resposta || mindy.text || '');
if (resposta && typeof resposta === 'object') resposta = resposta.resposta || JSON.stringify(resposta);
resposta = String(resposta).trim();
const cerca = resposta.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (cerca) {
  try {
    const o = JSON.parse(cerca[1]);
    if (o && typeof o.resposta === 'string') resposta = o.resposta;
  } catch (e) { resposta = cerca[1].trim(); }
}

const d = cons.descricao || {};
const linhas = cons.linhas || [];

// Quais colunas são numéricas de fato (não o que o modelo acha)
const numericas = linhas.length
  ? Object.keys(linhas[0]).filter((k) => linhas.every((l) => l[k] === null || typeof l[k] === 'number' ||
      (typeof l[k] === 'string' && l[k] !== '' && !isNaN(Number(l[k])))))
  : [];

const precisaImagem =
      linhas.length >= 2
   && linhas.length <= 30
   && numericas.length >= 1
   && (d.modo === 'agregado' || d.modo === 'fallback')
   && (d.dimensoes || []).length >= 1;

return [{
  json: {
    resposta,
    precisaImagem: !!precisaImagem,
    // compatibilidade com o contrato de saída atual do 7.2
    query: cons.sql,
    resultados: linhas,
    logica_aplicada: d.explicacao || '',
    // Bloco de diagnóstico: o que a suíte de teste confere. Não é a
    // resposta ao gestor — é como saber SE a consulta certa foi montada,
    // e não só se veio texto plausível.
    _diag: {
      dataset: d.dataset || null,
      modo: d.modo || null,
      recorte: d.recorte || null,
      recorte_tipo: d.recorte_tipo || null,
      campo_data: d.campo_data || null,
      periodo: d.periodo || null,
      dimensoes: d.dimensoes || [],
      metricas: d.metricas || [],
      filtros: (d.filtros || []).map((f) => f.rotulo),
      filtros_ignorados: (d.filtros_ignorados || []).map((f) => f.rotulo),
      ressalvas: d.ressalvas || [],
      ressalvas_internas: d.ressalvas_internas || [],
      origem: cons.origem,
      qtd_linhas: cons.qtd_linhas,
      vazio: !!cons.vazio,
      tentativas: cons.tentativas || 1,
      catalogo_versao: cons.catalogo_versao || null,
    },
  },
}];

// =====================================================================
// NÓ "Recusa honesta"
// =====================================================================
// O que o gestor recebe quando não foi possível montar a consulta.
// Nunca inventar número, nunca responder "0" sem explicar.
// =====================================================================

const ctx = $('Contexto do gestor').first().json;
const item = $input.first().json;

const e = item.erro && typeof item.erro === 'object' ? item.erro : null;
const motivo = e ? e.mensagem : (typeof item.erro === 'string' ? item.erro : null);
const sug = e && e.sugestoes && e.sugestoes.length ? e.sugestoes.slice(0, 6) : [];

let resposta = 'Não consegui montar essa consulta com os dados que tenho disponíveis.';
if (motivo) resposta += `\n\nO que travou: ${motivo}`;
if (sug.length) resposta += `\n\nPosso responder usando: ${sug.join(', ')}.`;
resposta += '\n\nSe reformular a pergunta indicando o período e o que quer ver (por filial, por colaborador, por doença), eu tento de novo.';

return [{
  json: {
    resposta,
    precisaImagem: false,
    query: item.sql || null,
    resultados: [],
    logica_aplicada: 'Consulta recusada na validação: ' + (e ? e.codigo : 'motivo não estruturado'),
    origem: 'recusa',
    qtd_linhas: 0,
  },
}];
